declarations.value:
${({ $header, $hovered }) => {
    if ($header) {
      return THEME_LIGHT.background.primary;
    }
    return $hovered
      ? THEME_LIGHT.background.secondary
      : THEME_LIGHT.background.primary;
  }}

${({ $header, $hovered, $footer }) => {
    if ($header || $footer) {
      return THEME_LIGHT.background.primary;
    }
    return $hovered
      ? THEME_LIGHT.background.secondary
      : THEME_LIGHT.background.primary;
  }}

${({ $isDragging, $isResizing, $animationsEnabled }) => {
    if ($isDragging || $isResizing) {
      return 'background-color 0.22s ease, box-shadow 0.14s ease, opacity 0.1s ease';
    }
    const base =
      'background-color 0.22s ease, box-shadow 0.22s ease, opacity 0.1s ease';
    if (!$animationsEnabled) {
      return base;
    }
    const springCurve = APP_PREVIEW_MOTION.windowSpringEase;
    const growDuration = '0.42s';
    return `${base}, height ${growDuration} ${springCurve}, width ${growDuration} ${springCurve}, transform ${growDuration} ${springCurve}`;
  }}

1px solid ${({ $active, $dark }) => {
      if (!$active) {
        return 'transparent';
      }
      return $dark
        ? editor.surface.activeSegmentBorder
        : terminal.toggle.activeSegmentBorder;
    }}

${({ $active, $dark }) => {
    if ($dark) {
      return $active ? editor.text.primary : editor.text.dim;
    }
    return $active ? terminal.text.primary : terminal.text.secondary;
  }}

${({ $active, $dark }) => {
      if ($active) {
        return $dark
          ? editor.surface.activeSegmentBackground
          : terminal.toggle.activeSegmentBackground;
      }
      return $dark
        ? editor.surface.rowHover
        : terminal.toggle.inactiveSegmentHoverBackground;
    }}

${({ $change }) => {
    if ($change === 'added') {
      return diff.rowAdded;
    }
    if ($change === 'removed') {
      return diff.rowRemoved;
    }
    return 'transparent';
  }}

${({ $header, $hovered }) => {
    if ($header) {
      return theme.background.primary;
    }

    return $hovered ? theme.background.secondary : theme.background.primary;
  }}

${({ $header, $hovered, $footer }) => {
    if ($header || $footer) {
      return theme.background.primary;
    }

    return $hovered ? theme.background.secondary : theme.background.primary;
  }}
